import{_ as t,o as e,c as s,a5 as i}from"./chunks/framework.bIR-4glx.js";const k=JSON.parse('{"title":"AI Task Brief: From Problem to Human Acceptance","description":"Before an AI learning or project task, define the real action, data boundary, sources, evaluation set, human ownership, cost, failure handling, and handover.","frontmatter":{"title":"AI Task Brief: From Problem to Human Acceptance","description":"Before an AI learning or project task, define the real action, data boundary, sources, evaluation set, human ownership, cost, failure handling, and handover.","updated":"2026-10-16T00:00:00.000Z","worksheetDownload":{"url":"/downloads/worksheets/ai-task-brief.en.md","name":"ai-task-brief.en.md"}},"headers":[],"relativePath":"en/templates/ai-task-brief.md","filePath":"en/templates/ai-task-brief.md","lastUpdated":1792108800000}'),n={name:"en/templates/ai-task-brief.md"};function r(o,a,d,l,p,c){return e(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="ai-task-brief-from-problem-to-human-acceptance" tabindex="-1">AI Task Brief: From Problem to Human Acceptance <a class="header-anchor" href="#ai-task-brief-from-problem-to-human-acceptance" aria-label="Permalink to &quot;AI Task Brief: From Problem to Human Acceptance&quot;">​</a></h1><p>Copy this into a private project directory before a model call. It is not a prompt collection. It is permission to start: when task, data, sources, acceptance, or ownership remain unclear, do not ask a model for the final result yet.</p><p>Do not include passwords, identity documents, precise addresses, medical privacy, children&#39;s data, customer records, unpublished vulnerabilities, or unauthorised third-party material. Redact sensitive material or use an organisation-approved environment.</p><h2 id="_1-task-and-ownership" tabindex="-1">1. Task and Ownership <a class="header-anchor" href="#_1-task-and-ownership" aria-label="Permalink to &quot;1. Task and Ownership&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># AI Task Brief - YYYY-MM-DD</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Real situation:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">User/audience:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Decision or action to complete:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Why now:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Deadline and non-negotiable checkpoints:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Final owner and human reviewer:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Who is affected if this is delayed or not done:</span></span></code></pre></div><p>Replace “learn AI” or “build an intelligent assistant” with an observable action, such as “a user can import a file in ten minutes and see an explainable report with sources and errors”.</p><h2 id="_2-inputs-sources-and-data-boundary" tabindex="-1">2. Inputs, Sources, and Data Boundary <a class="header-anchor" href="#_2-inputs-sources-and-data-boundary" aria-label="Permalink to &quot;2. Inputs, Sources, and Data Boundary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Input/claim</th><th>Type</th><th>Source, version, location</th><th>May reach model?</th><th>Verifier</th><th>Expiry condition</th></tr></thead><tbody><tr><td></td><td>fact / inference / experience / user data / third-party</td><td></td><td>public / redacted / approved / prohibited</td><td></td><td></td></tr></tbody></table><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Files and fields allowed:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Material deliberately withheld:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Data sensitivity: public / internal / confidential / restricted</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Collection, transfer, retention, and deletion dates:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Required consent obtained:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Copyright, licence, citation, and authorship requirements:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Minimum data scope the model can see:</span></span></code></pre></div><p>A source is not automatically true. Each critical claim must return to an original passage, version, data definition, or direct observation. Model links, numbers, and quotations still require human verification.</p><h2 id="_3-output-and-evaluation-set" tabindex="-1">3. Output and Evaluation Set <a class="header-anchor" href="#_3-output-and-evaluation-set" aria-label="Permalink to &quot;3. Output and Evaluation Set&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Final deliverable:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Format, length, and audience:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Observable definition of done:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Hard gates that must pass:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Acceptable variation:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Content that must not appear:</span></span></code></pre></div><p>Build a small, realistic evaluation set instead of only model-friendly examples:</p><table tabindex="0"><thead><tr><th>Sample</th><th>Input condition</th><th>Expected result</th><th>Unacceptable result</th><th>Actual result</th><th>Evidence location</th></tr></thead><tbody><tr><td>Normal case</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Boundary case</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Missing/conflicting input</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Redacted historical case</td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>Acceptance should answer whether facts are traceable, the action is complete, errors are visible, permissions are correct, and failure can stop. Fluent, fast, or human-like is not an acceptance standard.</p><h2 id="_4-ai-s-working-scope" tabindex="-1">4. AI&#39;s Working Scope <a class="header-anchor" href="#_4-ai-s-working-scope" aria-label="Permalink to &quot;4. AI&#39;s Working Scope&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AI may: ask / classify / propose explanations / give counterexamples / transcribe</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        / draft / suggest tests</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AI may not: make final factual decisions / invent sources / approve for the owner</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">             / cross permissions / complete a prohibited exam or application</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">             / publish or execute automatically</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Mode: diagnosis / assistance / candidate generation / batch processing / other</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Model, version, region, and call date:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">External tools, MCP servers, or other protocols and versions:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Read/write scope, authorizer, and revocation method for each tool:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Prompt, system instruction, or workflow version location:</span></span></code></pre></div><p>For a long-running or tool-using task, also record:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Run/task ID and parent task ID:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Async or synchronous mode; expected and maximum wall-clock time:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Checkpoint locations and resume procedure:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Maximum retries, timeout, and idempotency key:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Browser pages, screenshots, and external instructions treated as untrusted input:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Network egress allowlist and credential scope:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">External writes, receipts, and final environment state:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Human takeover point and emergency stop:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Supplier policy/version, effective date, region, and high-risk review:</span></span></code></pre></div><p>Ask the model to restate goal, input, limits, unknowns, and acceptance before generation. Version prompts, and never treat one chat window as the project&#39;s only record.</p><h2 id="_5-human-gates" tabindex="-1">5. Human Gates <a class="header-anchor" href="#_5-human-gates" aria-label="Permalink to &quot;5. Human Gates&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gate</th><th>Who confirms</th><th>Passing evidence</th><th>If it fails</th></tr></thead><tbody><tr><td>Source gate</td><td></td><td>Original link, version, location</td><td>Mark unverified; do not circulate</td></tr><tr><td>Fact gate</td><td></td><td>Sample checks and data definition</td><td>Delete or downgrade claim</td></tr><tr><td>Privacy/permission gate</td><td></td><td>Scope, consent, access record</td><td>Stop and redact</td></tr><tr><td>Quality gate</td><td></td><td>Evaluation set, edge cases, real feedback</td><td>Repair, narrow, or reject</td></tr><tr><td>Cost gate</td><td></td><td>Tokens, time, human rework, budget</td><td>Downgrade or stop</td></tr><tr><td>Tool authorization gate</td><td></td><td>Tool scope, call record, named authorization, and revocation method</td><td>Block the call or return to a person</td></tr><tr><td>Ownership gate</td><td></td><td>Named approval and disclosure</td><td>Do not publish or execute</td></tr></tbody></table><p>Critical decisions cannot be approved only by the generator, an automated score, or one developer alone. High-risk domains return to current primary sources and qualified professionals.</p><h2 id="_6-cost-retention-and-reversibility" tabindex="-1">6. Cost, Retention, and Reversibility <a class="header-anchor" href="#_6-cost-retention-and-reversibility" aria-label="Permalink to &quot;6. Cost, Retention, and Reversibility&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Call volume, time, and cost ceiling:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Human review and rework budget:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Does data enter training, logs, or third-party retention:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Acceptable latency and downgrade path:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Version that can be withdrawn, rerun, or restored:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Release scope and pilot audience:</span></span></code></pre></div><p>A cheap call that causes a privacy incident, wrong decision, or major rework is not cheap in reality. Record human time, review, failure, reruns, and communication in addition to model fees.</p><h2 id="_7-failure-pause-and-rollback" tabindex="-1">7. Failure, Pause, and Rollback <a class="header-anchor" href="#_7-failure-pause-and-rollback" aria-label="Permalink to &quot;7. Failure, Pause, and Rollback&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Trigger</th><th>Immediate action</th><th>Notify</th><th>Recovery/rollback location</th></tr></thead><tbody><tr><td>Source or version cannot be found</td><td>Stop circulation; return to original</td><td></td><td></td></tr><tr><td>Evaluation hard gate fails</td><td>Block release or automatic action</td><td></td><td></td></tr><tr><td>Input crosses permission boundary</td><td>Stop upload; revoke access</td><td></td><td></td></tr><tr><td>Cost/latency exceeds ceiling</td><td>Downgrade, throttle, or stop</td><td></td><td></td></tr><tr><td>Real user reports harm</td><td>Remove, preserve evidence, escalate</td><td></td><td></td></tr></tbody></table><p>Without a named stop owner, notification path, and known-good version, the task is not ready for a real workflow.</p><h2 id="_8-handover-and-public-disclosure" tabindex="-1">8. Handover and Public Disclosure <a class="header-anchor" href="#_8-handover-and-public-disclosure" aria-label="Permalink to &quot;8. Handover and Public Disclosure&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Current state: not started / experiment / internal pilot / limited release / delivered / stopped</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Completed work and evidence locations:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Open questions and risks:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Smallest next task:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Handover owner, date, and access:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What readers/users need to know about AI involvement:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Source, privacy, copyright, and conflict-of-interest note:</span></span></code></pre></div><p>The next operator should not search chat history to discover what to do. Public work should state which step used a tool, which facts a person confirmed, and which content remains a candidate.</p><h2 id="_9-preflight-check" tabindex="-1">9. Preflight Check <a class="header-anchor" href="#_9-preflight-check" aria-label="Permalink to &quot;9. Preflight Check&quot;">​</a></h2><ul><li>[ ] Audience, action, deadline, and owner are explicit.</li><li>[ ] Input fields, sensitivity, consent, copyright, and retention are confirmed.</li><li>[ ] Critical sources, versions, and expiry conditions are traceable.</li><li>[ ] Normal, boundary, conflict, and redacted historical cases are in the evaluation set.</li><li>[ ] AI may/may-not scope is explicit.</li><li>[ ] Long-running checkpoints, retry/idempotency rules, browser-input boundary, and network egress are recorded when applicable.</li><li>[ ] Human gates, cost ceiling, stop conditions, and rollback location are named.</li><li>[ ] Handover, disclosure, and next review date are set.</li></ul>`,34)])])}const u=t(n,[["render",r]]);export{k as __pageData,u as default};
